bool FileRequestValidator::Accept(mojo::Message* message) {
  const char* name = ::filesystem::mojom::File::Name_;
  return mojo::internal::ValidateRequestGenericPacked(message, name, kFileValidationInfo);
}

bool FileResponseValidator::Accept(mojo::Message* message) {
  const char* name = ::filesystem::mojom::File::Name_;
  return mojo::internal::ValidateResponseGenericPacked(message, name, kFileValidationInfo);
}


